classDiagram
    class Bookmark {
        +String id
        +String title
        +String url
        +String dom_html
        +save()
    }
    class Parser {
        +parse(html) JsonData
        +extractMarkdown(dom) Array
        +extractLatex(dom) Array
    }
    class Reader {
        +loadJson(dir) Array
        +render(json) HTMLElement
    }
    Bookmark --> Parser : 传递HTML
    Parser --> Reader : 生成JSON
    Reader --> Bookmark : 显示内容
